diff --git a/src/main/java/com/example/ContactView.java b/src/main/java/com/example/ContactView.java
new file mode 100644
index 0000000..7f4c373
--- /dev/null
+++ b/src/main/java/com/example/ContactView.java
@@ -0,0 +1,167 @@
+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final MessageStore messageStore;
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<Message> messageGrid = new Grid<>(Message.class, false);
+    private boolean clearingAfterSend;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        setSizeFull();
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        nameField.setValue("");
+        emailField.setValue("");
+        phoneField.setValue("");
+        messageField.setValue("");
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+
+        FormLayout form = new FormLayout();
+        form.add(nameField, emailField, phoneField, messageField);
+        form.add(sendButton);
+        sendButton.addClickListener(event -> sendMessage());
+        addAttachListener(event -> event.getUI()
+                .addShortcutListener(() -> {
+                    if (sendButton.isEnabled()) {
+                        sendMessage();
+                    }
+                }, Key.ENTER)
+                .bindLifecycleTo(this));
+
+        nameField.addValueChangeListener(event -> fieldEdited());
+        emailField.addValueChangeListener(event -> fieldEdited());
+        phoneField.addValueChangeListener(event -> fieldEdited());
+        messageField.addValueChangeListener(event -> fieldEdited());
+
+        messageGrid.addColumn(Message::name).setHeader("Name");
+        messageGrid.addColumn(Message::message).setHeader("Message");
+        messageGrid.setItems(messageStore.getNewestFirst());
+
+        add(form, messageGrid);
+    }
+
+    private void fieldEdited() {
+        if (!clearingAfterSend) {
+            sendButton.setEnabled(true);
+            clearValidation();
+        }
+    }
+
+    private void sendMessage() {
+        clearValidation();
+        boolean valid = true;
+
+        String name = nameField.getValue();
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        String message = messageField.getValue();
+
+        if (name.isBlank()) {
+            nameField.setErrorMessage("Name is required");
+            nameField.setInvalid(true);
+            valid = false;
+        }
+
+        String normalizedEmail = email.trim();
+        if (!normalizedEmail.isEmpty()
+                && new EmailValidator("Enter a valid e-mail address").apply(normalizedEmail, null).isError()) {
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            emailField.setInvalid(true);
+            valid = false;
+        } else if (normalizedEmail.isEmpty() && phone.isBlank()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            valid = false;
+        }
+
+        if (message.isBlank()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            valid = false;
+        } else if (message.length() > 500) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new Message(name, normalizedEmail, phone, message));
+        messageGrid.setItems(messageStore.getNewestFirst());
+        Notification.show("Message sent");
+
+        clearingAfterSend = true;
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        clearingAfterSend = false;
+        clearValidation();
+        sendButton.setEnabled(false);
+    }
+
+    private void clearValidation() {
+        nameField.setInvalid(false);
+        nameField.setErrorMessage("");
+        emailField.setInvalid(false);
+        emailField.setErrorMessage("");
+        messageField.setInvalid(false);
+        messageField.setErrorMessage("");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (nameField.getValue().isEmpty() && emailField.getValue().isEmpty()
+                && phoneField.getValue().isEmpty() && messageField.getValue().isEmpty()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add(new Paragraph("You have unsent changes. Discard them?"));
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            dialog.close();
+            navigation.cancel();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(keepEditing, discard);
+        dialog.open();
+    }
+}
