+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactBrowserTest extends AbstractBasePlaywrightIT {
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void sendsAndConfirmsNavigationInBrowser() {
+        var page = getPage();
+        page.getByLabel("Name").fill("Sam");
+        page.getByLabel("Phone").fill("555-0123");
+        page.getByLabel("Message").fill("Browser submitted message");
+        page.getByLabel("Message").press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        GridElement.get(page).assertRowCount(1);
+        GridElement.get(page).assertCellContent(0, "Name", "Sam");
+        GridElement.get(page).assertCellContent(0, "Message", "Browser submitted message");
+        assertTrue(page.getByRole(AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Send")).isDisabled());
+        assertEquals("", page.getByLabel("Name").inputValue());
+
+        page.getByLabel("Name").fill("draft");
+        page.waitForFunction("() => !document.querySelector('vaadin-button').hasAttribute('disabled')");
+        assertFalse(page.getByRole(AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Send")).isDisabled());
+        page.getByRole(AriaRole.LINK,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).click();
+        new DialogElement(page).assertOpen();
+        page.getByRole(AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertTrue(page.url().endsWith("/contact"));
+        assertEquals("draft", page.getByLabel("Name").inputValue());
+
+        page.getByRole(AriaRole.LINK,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).click();
+        new DialogElement(page).assertOpen();
+        page.getByRole(AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Discard")).click();
+        page.waitForURL("**/about");
+        assertTrue(page.getByRole(AriaRole.HEADING,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).isVisible());
+    }
+}
